<div class="file-action-link mcp-call" title="Argumentos: {"path": "script.js", "content": "// Variables globales para la simulación
let particles = [];
const NUM_PARTICLES = 100;

// Clase simple para una partícula de fuego
class Particle {
    constructor(x, y) {
        this.position = createVector(x, y);
        this.velocity = createVector(random(-1, 1), random(-1, 1));
        this.acceleration = createVector(0, 0); // Para la interacción con el mouse/fluid
        this.life = random(150, 255); // Vida en píxeles/fotogramas
        thi...">🛠️ Herramienta: <strong>write_file</strong></div>

    applyForce(force) {
        this.acceleration.add(force); 
    }

    update() {
        // Aplicamos la aceleración y actualizamos la velocidad/posición
        this.velocity.add(this.acceleration);
        this.position.add(this.velocity);
        this.acceleration.mult(0); // Resetear aceleración
        this.life -= 2; // Disminuye la vida
    }

    display() {
        let alpha = map(this.life, 0, 255, 0, 255); // Transparencia basada en la vida
        fill(255, 100, 0, alpha); // Color naranja/rojo simulando fuego
        noStroke();
        ellipse(this.position.x, this.position.y, this.size, this.size * 1.5);
    }
}

function setup() {
    // Inicializa el canvas para que cubra toda la ventana (Fullscreen)
    createCanvas(windowWidth, windowHeight);
    background(0, 0, 0, 0); // Fondo negro

    // Inicializar las partículas
    particles = [];
    for (let i = 0; i < NUM_PARTICLES; i++) {
        particles.push(new Particle(random(width), random(height)));
    }
    console.log("Proyecto p5.js de Fuego Inicializado.");
}

function draw() {
    // Dibujar un fondo semi-transparente para crear el efecto de estela/resplandor
    background(0, 0, 0, 20); 

    let mouseForce = createVector(mouseX - width / 2, mouseY - height / 2).normalize();

    // 1. Actualizar y dibujar partículas
    for (let i = 0; i < particles.length; i++) {
        let p = particles[i];

        // Aplicar una fuerza de atracción/repulsión basada en el mouse (Interacción)
        let mouseInteraction = p5.Vector.sub(createVector(mouseX, mouseY), p.position);
        mouseInteraction.setMag(0.05); // Fuerza suave
        p.applyForce(mouseInteraction); 

        p.update();
        p.display();
    }

    // 2. Manejar ciclo de vida y regeneración
    particles = particles.filter(p => p.life > 0);
    // Reemplazar partículas muertas
    while (particles.length < NUM_PARTICLES) {
        particles.push(new Particle(random(width), random(height)));
    }
}

// Adaptar el canvas si el usuario cambia el tamaño de la ventana
function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
    background(0, 0, 0, 0);
}
"}

